<input type='range' id='slD' min='2' max='10' value='2'><span class='val' id='vD'>2</span></div></div><div class='panel'><div class='formula' id='formula'></div><div class='comparison'><div class='comp-box comp-vol'><div class='comp-label'>Volumes (A^L)</div><div class='comp-val' id='volCount' style='color:#60d060'></div></div><div class='comp-box comp-cat'><div class='comp-label'>Catalog Schemes (D^(A^L))</div><div class='comp-val' id='catCount' style='color:#c060f0'></div></div></div><canvas id='chart' height='280'></canvas><div class='explanation' id='explain'></div></div><div class='panel'><h2 style='color:#80b0ff;margin-bottom:10px'>The Diagonal Argument</h2><div id='diagonal' style='font-family:monospace;font-size:.85em;line-height:1.6;overflow-x:auto'></div></div></div><script>const slA=document.getElementById('slA'),slL=document.getElementById('slL'),slD=document.getElementById('slD');function update(){const A=+slA.value,L=+slL.value,D=+slD.value;document.getElementById('vA').textContent=A;document.getElementById('vL').textContent=L;document.getElementById('vD').textContent=D;const vols=Math.pow(A,L),cats=Math.pow(D,vols);document.getElementById('formula').innerHTML=A+'^'+L+' = '+vols+' &lt; '+D+'^'+vols+(cats<1e15?' = '+cats.toLocaleString():' = 10^'+(vols*Math.log10(D)).toFixed(1));document.getElementById('volCount').textContent=vols.toLocaleString();document.getElementById('catCount').textContent=cats<1e15?cats.toLocaleString():'10^'+(vols*Math.log10(D)).toFixed(1);const logV=L*Math.log10(A),logC=vols*Math.log10(D);document.getElementById('explain').innerHTML='<b>Gap:</b> The catalog space is 10^'+(logC-logV).toFixed(1)+' times larger than the Library.<br><b>Meaning:</b> There are '+vols+' volumes but '+(cats<1e15?cats.toLocaleString():'about 10^'+(logC).toFixed(1))+' ways to classify them.<br><b>Theorem (no_catalog_embedding):</b> No injection from catalog schemes to volumes exists.';drawChart(A,L,D,vols,cats);drawDiagonal(A,L,D,vols)}function drawChart(A,L,D,vols,cats){const c=document.getElementById('chart'),ctx=c.getContext('2d');c.width=c.offsetWidth*2;c.height=280*2;ctx.scale(2,2);const W=c.width/2,H=c.height/2;ctx.fillStyle='#0a0a1a';ctx.fillRect(0,0,W,H);const logV=Math.log10(Math.max(vols,1)),logC=vols>0?vols*Math.log10(D):1;const maxLog=Math.max(logV,logC,1);const barW=80,gap=60,startX=W/2-barW-gap/2;const maxH=H-80;const hV=Math.max(5,maxH*logV/maxLog),hC=Math.max(5,maxH*Math.min(logC,maxLog*3)/Math.max(maxLog*3,1));const g1=ctx.createLinearGradient(0,H-40-hV,0,H-40);g1.addColorStop(0,'#40a040');g1.addColorStop(1,'#206020');ctx.fillStyle=g1;ctx.fillRect(startX,H-40-hV,barW,hV);ctx.fillStyle='#60d060';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillText('Volumes',startX+barW/2,H-20);ctx.fillText(vols<1e9?vols.toLocaleString():'10^'+logV.toFixed(1),startX+barW/2,H-45-hV);const x2=startX+barW+gap;const g2=ctx.createLinearGradient(0,H-40-hC,0,H-40);g2.addColorStop(0,'#a040c0');g2.addColorStop(1,'#602080');ctx.fillStyle=g2;ctx.fillRect(x2,H-40-hC,barW,hC);ctx.fillStyle='#c060f0';ctx.fillText('Schemes',x2+barW/2,H-20);ctx.fillText(cats<1e9?cats.toLocaleString():'10^'+logC.toFixed(1),x2+barW/2,H-45-hC);if(hC>=maxH){ctx.fillStyle='#ff6060';ctx.font='12px sans-serif';ctx.fillText('(truncated)',W/2,20)}}function drawDiagonal(A,L,D,vols){if(vols>16||vols<2){document.getElementById('diagonal').innerHTML='<i style=\"color:#6080a0\">(Diagonal visualization for A^L <= 16)</i>';return}const rows=Math.min(vols,8);let html='<div style=\"color:#8090b0\">Build table f(v_i)(v_j) and flip the diagonal:</div><br>';html+='<table style=\"border-collapse:collapse;margin:0 auto\"><tr><td></td>';for(let j=0;j<rows;j++)html+='<td style=\"padding:3px 8px;color:#6080a0;text-align:center\">v'+j+'</td>';html+='<td style=\"padding:3px 12px;color:#ff6060\">diag</td></tr>';for(let i=0;i<rows;i++){html+='<tr><td style=\"padding:3px 8px;color:#6080a0\">f(v'+i+')</td>';for(let j=0;j<rows;j++){const val=(i*3+j*7+i*j)%D;const isDi