'><h2>Singleton Bound for BabelCodes</h2><p style='color:#8090b0;font-size:.9em;margin-bottom:10px'>Max codewords with min distance d: |C| &le; A^(L-d+1)</p><table><thead><tr><th>Min Distance d</th><th>Bound A^(L-d+1)</th><th>Fraction</th><th>Error Correction</th></tr></thead><tbody id='singletonTable'></tbody></table></div><div class='panel'><h2>Compression Impossibility</h2><p style='color:#8090b0;font-size:.9em;margin-bottom:10px'>Compressing L to M: at most A^M volumes survive</p><div class='row'><label>Target Length M:</label><input type='range' id='pM' min='0' max='32' value='8'><span class='val' id='vM'>8</span></div><div id='compressionStats' style='margin:15px 0'></div><div class='meter' id='compressionMeter'></div><div id='compressionVerdict' style='text-align:center;margin:10px 0;font-size:1.1em'></div></div><div class='panel'><h2>Library Geometry</h2><div id='geometry' style='display:flex;flex-wrap:wrap;gap:20px;justify-content:center'></div></div></div><script>function fmt(n){if(n>=1e15)return'~10^'+(Math.log10(n)).toFixed(1);if(n>=1e6)return n.toExponential(2);return n.toLocaleString()}function update(){const A=+document.getElementById('pA').value;const L=+document.getElementById('pL').value;let M=+document.getElementById('pM').value;document.getElementById('pM').max=L;if(M>L){M=L;document.getElementById('pM').value=M}document.getElementById('vA').textContent=A;document.getElementById('vL').textContent=L;document.getElementById('vM').textContent=M;const total=Math.pow(A,L);let st='';const steps=[1,2,Math.max(1,Math.floor(L/4)),Math.max(1,Math.floor(L/2)),Math.max(1,Math.floor(3*L/4)),L];const unique=[...new Set(steps)].filter(d=>d>=1&&d<=L).sort((a,b)=>a-b);unique.forEach(d=>{const bound=Math.pow(A,L-d+1);const frac=bound/total;const corr=Math.floor((d-1)/2);st+='<tr><td>'+d+'</td><td>'+fmt(bound)+'</td><td>'+(frac*100).toFixed(frac<0.01?4:2)+'%</td><td>corrects '+corr+' errors</td></tr>'});document.getElementById('singletonTable').innerHTML=st;const survivors=Math.pow(A,M);const destroyed=total-survivors;const survPct=100*survivors/total;const destPct=100-survPct;document.getElementById('compressionStats').innerHTML='<div style=\"display:flex;justify-content:space-around;flex-wrap:wrap\"><div style=\"text-align:center\"><div style=\"font-size:2em;color:#f0c040\">'+fmt(total)+'</div><div style=\"color:#6080a0;font-size:.8em\">Total Volumes</div></div><div style=\"text-align:center\"><div style=\"font-size:2em;color:#60d060\">'+fmt(survivors)+'</div><div style=\"color:#6080a0;font-size:.8em\">Max Survivors</div></div><div style=\"text-align:center\"><div style=\"font-size:2em;color:#ff6060\">'+fmt(destroyed)+'</div><div style=\"color:#6080a0;font-size:.8em\">Min Destroyed</div></div></div>';const meter=document.getElementById('compressionMeter');meter.innerHTML='<div class=\"meter-survive\" style=\"width:'+Math.max(1,survPct)+'%\">'+(survPct>5?survPct.toFixed(1)+'%':'')+'</div><div class=\"meter-destroy\" style=\"width:'+Math.max(1,destPct)+'%\">'+(destPct>5?destPct.toFixed(1)+'%':'')+'</div>';const majorityDestroyed=destroyed>survivors;document.getElementById('compressionVerdict').innerHTML=M<L?'<span class=\"'+(majorityDestroyed?'bad':'good')+'\">'+(majorityDestroyed?'MAJORITY DESTROYED (majority_incompressible)':'Survivors may exceed destroyed')+'</span>':'<span class=\"good\">No compression (M = L)</span>';document.getElementById('geometry').innerHTML='<div style=\"text-align:center;padding:10px 20px;background:#1a1a3a;border-radius:8px\"><div style=\"font-size:2em;color:#f0c040\">'+fmt(total)+'</div><div style=\"color:#6080a0;font-size:.8em\">Volumes (A^L)</div></div><div style=\"text-align:center;padding:10px 20px;background:#1a1a3a;border-radius:8px\"><div style=\"font-size:2em;color:#80c0ff\">'+(L*(A-1)).toLocaleString()+'</div><div style=\"color:#6080a0;font-size:.8em\">Degree L(A-1)</div></div><div style=\"text-align:center;padding:10px 20px;background:#1a1a3a;border-radius:8px\"><div style=\"font-size:2em;color:#ff8060\">'+L+'</div><div style=\"color:#6080a0;font-size:.8em\">Diameter</div></div>'}document.querySelectorAll('input[type=range]').forEach(el=>el.oninput=update);update()</script></body></html>"
