n='2' max='16' value='8'></div><div class='control-group'><label><button onclick='randomize()' style='background:#2a4a7a;color:white;border:none;padding:6px 14px;border-radius:6px;cursor:pointer'>Randomize</button></label></div></div></div><div class='panel'><h2>Volume V (click cells to change)</h2><div id='volV' class='volume-display'></div><h2>Volume W (click cells to change)</h2><div id='volW' class='volume-display'></div></div><div class='panel'><h2>Distance Analysis</h2><div style='text-align:center'><div class='stat'><div class='stat-value' id='distVal'>0</div><div class='stat-label'>Hamming Distance</div></div><div class='stat'><div class='stat-value' id='maxDist'>0</div><div class='stat-label'>Max Distance (L)</div></div><div class='stat'><div class='stat-value' id='degreeVal'>0</div><div class='stat-label'>Neighbors per Volume</div></div><div class='stat'><div class='stat-value' id='totalVols'>0</div><div class='stat-label'>Total Volumes (A^L)</div></div></div></div><div class='panel'><h2>Theorems Verified</h2><div id='theorems' style='font-size:.9em;line-height:1.8'></div></div></div><script>let A=4,L=8,V=[],W=[];function init(){A=parseInt(document.getElementById('alphaSize').value);L=parseInt(document.getElementById('bookLen').value);V=Array.from({length:L},()=>Math.floor(Math.random()*A));W=Array.from({length:L},()=>Math.floor(Math.random()*A));render()}function render(){renderVol('volV',V,W);renderVol('volW',W,V);let d=hammingDist(V,W);document.getElementById('distVal').textContent=d;document.getElementById('maxDist').textContent=L;document.getElementById('degreeVal').textContent=(L*(A-1)).toLocaleString();let total=Math.pow(A,L);document.getElementById('totalVols').textContent=total>1e9?A+'^'+L:total.toLocaleString();let t='';t+='<div style=\"color:'+(d<=L?'#60d060':'#ff6060')+'\">hammingDist_le_length: d(V,W) = '+d+' <= '+L+' = L</div>';t+='<div style=\"color:#60d060\">hammingDist_comm: d(V,W) = d(W,V) = '+d+'</div>';t+='<div style=\"color:#60d060\">b